mapper.sql:
WHERE s.delete_yn = 'N'
AND s.use_yn = #{search.useYn}
AND (s.site_code LIKE CONCAT('%', #{search.keyword}, '%') OR s.site_name LIKE CONCAT('%', #{search.keyword}, '%') OR s.domain LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT COUNT(1)
  FROM tb_site
 WHERE site_code  = #{siteCode}
   AND delete_yn  = 'N'

  AND site_id <> #{excludeSiteId}

SELECT COUNT(1)
  FROM tb_site
 WHERE domain     = #{domain}
   AND delete_yn  = 'N'

  AND site_id <> #{excludeSiteId}
